for k,v in V.items():
    h = src.replace('--accent:#4A6B4F', '--accent:'+v['accent']).replace('--accent:#8DB492', '--accent:'+v['accent_d'])
    h = h.replace('✦ Thought for today', v['label'])
    h = re.sub(r'const Q=\[.*?\];', 'const Q='+json.dumps(v['q'], ensure_ascii=False)+';', h, flags=re.S)
    h = h.replace("'sf_h24'", "'sf_h24_"+k+"'")
    if k=='journal':
        h = h.replace("'<b>“</b>'+Q[doy%Q.length]+'<b>”</b>'", "Q[doy%Q.length]")
    open(f'widgets/{k}/today.html','w').write(h)
    print(k, len(h))
